SELECT cr.cr_order_number, cr.cr_returned_date_sk, i.i_product_name, i.i_brand, i.i_category, w.w_city, w.w_state, sm.sm_type AS ship_mode_type, cr.cr_return_quantity, cr.cr_refunded_cash, cr.cr_store_credit, cr.cr_reversed_charge, CASE WHEN cr.cr_refunded_cash > (cr.cr_store_credit + cr.cr_reversed_charge) THEN 'Suspicious' ELSE 'Normal' END AS refund_flag, ROW_NUMBER() OVER (PARTITION BY cr.cr_returning_customer_sk ORDER BY cr.cr_returned_date_sk DESC) AS return_seq, SUM(cr.cr_net_loss) OVER (PARTITION BY cr.cr_returning_customer_sk) AS total_customer_net_loss, AVG(cr.cr_return_quantity) OVER (PARTITION BY cr.cr_returning_customer_sk) AS avg_return_qty_per_customer FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk WHERE cr.cr_returned_date_sk >= 20200101 ORDER BY cr.cr_returning_customer_sk, cr.cr_returned_date_sk DESC LIMIT 100
